 b=p.chromium.launch(**({"executable_path": os.environ["NEON_CHROME"], "args": ["--no-sandbox"]} if os.environ.get("NEON_CHROME") else {}));c=b.new_context(viewport={'width':1280,'height':720});pg=c.new_page();errs=[];pg.on('pageerror',lambda e:errs.append(str(e)));pg.goto(URL)
 # complete natural waves and boss with aim controller. God isolates tuning only; no arbitrary damage/XP.
 result=pg.evaluate('''()=>{NR.rng.seed(99);NR.game.startRun(true);NR.player.god=true;const W=NR.world,p=NR.player.p,I=NR.input;let bossStart=0,bossTime=0,levelWaves=[],lastLevel=1,maxes={enemies:0,bullets:0,enemyBullets:0,gems:0,particles:0,floating:0,effects:0};for(let f=0;f<60*1200;f++){const st=NR.game.state;if(st==='LEVEL_UP'||st==='BOSS_REWARD'){NR.ui.update(.5);NR.ui.choose(0);NR.ui.update(1);continue;}if(st==='BOSS_INTRO'){NR.game.step(3);bossStart=W.runTime;continue;}let e=W.boss&&!W.boss.dead?W.boss:W.enemies.find(e=>!e.dead&&!e.cloak);if(e){I.aim.x=e.x;I.aim.y=e.y;}else if(W.gems.list.length){const g=W.gems.list[0];I.aim.x=g.x;I.aim.y=g.y;}I.mouse.down=true;I.keys.clear();let dest=W.boss?{x:W.boss.x,y:W.boss.y+W.boss.r+170}:W.gems.list[0]||{x:W.W/2,y:W.H/2};if(p.x<dest.x-15)I.keys.add('d');if(p.x>dest.x+15)I.keys.add('a');if(p.y<dest.y-15)I.keys.add('s');if(p.y>dest.y+15)I.keys.add('w');NR.game.step(1/60);if(p.level!==lastLevel){levelWaves.push({level:p.level,wave:W.wave,time:W.runTime});lastLevel=p.level;}if(W.bossKills>0&&!bossTime)bossTime=W.runTime-bossStart;maxes.enemies=Math.max(maxes.enemies,W.enemies.length);for(const k of ['bullets','enemyBullets','gems','particles','floating'])maxes[k]=Math.max(maxes[k],W[k].list.length);maxes.effects=Math.max(maxes.effects,W.effects.length);if(W.wave>=11)break;}return{wave:W.wave,level:p.level,bossKills:W.bossKills,bossTime,kills:W.kills,runTime:W.runTime,levelWaves,maxes,state:NR.game.state};}''');results['natural_wave_playthrough']=result;print('playthrough',json.dumps(result))
 # boss fire-only base weapon tuning, moving aim controller god active
 tuning=pg.evaluate('''()=>{const out={};for(const weapon of ['pulse','nova','rail','arc','void']){NR.game.startRun(true);NR.player.god=true;NR.player.p.weapon=weapon;NR.player.p.upgrades={};NR.player.p.pending=0;NR.world.wave=5;NR.world.spawnLeft=0;NR.world.queue=[];NR.world.cleared=true;NR.bosses.create('overlord',1);NR.game.setState('BOSS_FIGHT');const W=NR.world,p=NR.player.p,I=NR.input;let time=0;for(let f=0;f<60*240;f++){if(!W.boss||W.boss.dead)break;p.x=W.boss.x;p.y=Math.min(W.H-30,W.boss.y+W.boss.r+50);I.aim.x=W.boss.x;I.aim.y=W.boss.y;I.mouse.down=weapon==='rail'?f%42<32:true;I.keys.clear();NR.game.step(1/60);time+=1/60;if(NR.game.state==='LEVEL_UP'){NR.ui.update(.5);NR.ui.choose(0);NR.ui.update(1);p.upgrades={};p.pending=0;}}out[weapon]={time,remaining:W.boss?W.boss.hp:0,dead:!W.boss||W.boss.dead};}return out;}''');results['boss_tuning']=tuning;print('boss tuning',json.dumps(tuning))
 # 30-min game-time soak with cheats to keep long-run safe, chooses upgrades and cycles boss
 soak=pg.evaluate('''()=>{NR.game.startRun(true);NR.player.god=true;NR.rng.seed(5);const W=NR.world,p=NR.player.p,I=NR.input;let max={enemies:0,bullets:0,enemyBullets:0,gems:0,particles:0,floating:0,effects:0},bad=[];for(let f=0;f<60*1800;f++){const st=NR.game.state;if(st==='LEVEL_UP'||st==='BOSS_REWARD'){NR.ui.update(.5);NR.ui.choose(0);NR.ui.update(1);}if(st==='BOSS_INTRO')NR.game.step(3);if(W.boss&&!W.boss.dead){W.boss.invuln=0;NR.bosses.hit(100);}let e=W.enemies.find(e=>!e.dead&&!e.cloak);I.aim.x=e?e.x:W.W;I.aim.y=e?e.y:W.H/2;I.mouse.down=true;I.keys.clear();I.keys.add(f%600<300?'a':'d');I.keys.add(f%720<360?'w':'s');if(f%180===0)I.queueDash();NR.game.step(1/60);if(f%60===0)NR.render.frame(true);for(const e of W.enemies){if(!Number.isFinite(e.x)||!Number.isFinite(e.y))bad.push('enemy NaN');}if(!Number.isFinite(p.x)||!Number.isFinite(p.hp))bad.push('player NaN');max.enemies=Math.max(max.enemies,W.enemies.length);for(const k of ['bullets','enemyBullets','gems','particles','floating'])max[k]=Math.max(max[k],W[k].list.length);max.effects=Math.max(max.effects,W.effects.length);}return{wave:W.wave,gameTime:W.runTime,max,bad:[...new Set(bad)],glowCache:NR.glow.size(),voices:NR.audio.voiceCount()};}''');results['soak_30min_game_time']=soak;print('soak',json.dumps(soak))
